properties.--unified-seek-offset-x:
calc(max(0px,
        var(--half-width) + var(--unified-seek-edge-padding) - var(--scrubber-container-x) - var(
            --progress-left-buffer
          )) + min(0px,
        var(--progress-width) + var(--progress-right-buffer) - var(--unified-seek-edge-padding) - var(
            --scrubber-container-x
          ) - var(--half-width)))

properties.--unified-seek-bounce-offset-x:
calc(max(0px,
        calc(var(--half-width) * var(--unified-seek-bounce-scale)) + var(--unified-seek-edge-padding) - var(--scrubber-container-x) - var(
            --progress-left-buffer
          )) + min(0px,
        var(--progress-width) + var(--progress-right-buffer) - var(--unified-seek-edge-padding) - var(
            --scrubber-container-x
          ) - calc(var(--half-width) * var(--unified-seek-bounce-scale))))
